<!--
  Ficheiro: src/components/live/M3uImportDialog.vue
  Tipo: Diálogo Vue.
  Função: Lê, pré-visualiza, seleciona e importa canais M3U.
-->
<script setup lang="ts">
import { computed,ref } from "vue";import { channelRepository,streamLinkRepository } from "@/domain/repositories";import { parseM3u,type M3uItem } from "@/domain/live/m3u";import { findM3uDuplicate } from "@/domain/live/m3uDuplicate";import type { ChannelRecord } from "@/types/records";
const props=defineProps<{open:boolean;existing:ChannelRecord[]}>();const emit=defineEmits<{close:[];imported:[number]}>();const items=ref<M3uItem[]>([]),fileName=ref(""),error=ref(""),importing=ref(false),progress=ref(0),query=ref("");const visible=computed(()=>{const q=query.value.toLocaleLowerCase("pt-PT");return items.value.filter(x=>!q||[x.name,x.groupTitle,x.tvgId].some(v=>v.toLocaleLowerCase("pt-PT").includes(q)))});const selected=computed(()=>items.value.filter(x=>x.selected&&!x.errors.length));async function readFile(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;fileName.value=file.name;error.value="";try{items.value=parseM3u(await file.text())}catch(c){items.value=[];error.value=c instanceof Error?c.message:String(c)}}function selectAll(value:boolean){for(const item of visible.value)item.selected=value&&!item.errors.length}async function run(){if(!selected.value.length)return;importing.value=true;progress.value=0;let count=0;try{for(const item of selected.value){const duplicate=findM3uDuplicate(item,props.existing);if(duplicate.kind&&duplicate.kind!=="name"){progress.value++;continue}const channel=await channelRepository.create({nome:item.name,url_stream:item.url,tvg_id:item.tvgId,tvg_name:item.tvgName,tvg_logo_url:item.tvgLogo,playlist_origem:fileName.value,adulto:item.adult,ativo:true,cemiterio:false,qualidade:"Desconhecida"}) as ChannelRecord;await streamLinkRepository.create({canal_tv:channel.id,url:item.url,rotulo:"Importado da playlist",tipo:/\.m3u8(?:$|[?#])/i.test(item.url)?"hls":"http",qualidade:"Desconhecida",prioridade:0,ativo:true});count++;progress.value++}emit("imported",count)}catch(c){error.value=c instanceof Error?c.message:String(c)}finally{importing.value=false}}
</script>
<template><Teleport to="body"><div v-if="open" class="dialog-backdrop" @click.self="!importing&&emit('close')"><section class="dialog-panel m3u-import" role="dialog" aria-modal="true" aria-labelledby="m3u-title"><div class="dialog-header"><div><p class="eyebrow">IPTV</p><h2 id="m3u-title">Importar playlist M3U</h2></div><button class="icon-button" type="button" aria-label="Fechar importador" :disabled="importing" @click="emit('close')">×</button></div><label class="form-field"><span>Playlist M3U ou M3U8</span><input type="file" accept=".m3u,.m3u8,application/vnd.apple.mpegurl,audio/x-mpegurl" @change="readFile"/></label><div v-if="error" class="form-alert form-alert-error" role="alert">{{error}}</div><template v-if="items.length"><div class="m3u-summary"><strong>{{items.length}} entradas</strong><span>{{selected.length}} selecionadas</span><span>{{items.filter(x=>x.errors.length).length}} inválidas</span></div><div class="m3u-toolbar"><input v-model.trim="query" type="search" placeholder="Pesquisar nome, grupo ou TVG-ID"/><button class="button button-secondary" type="button" @click="selectAll(true)">Selecionar visíveis</button><button class="button button-secondary" type="button" @click="selectAll(false)">Limpar visíveis</button></div><div class="m3u-list"><label v-for="item in visible" :key="`${item.url}-${item.name}`" class="m3u-row"><input v-model="item.selected" type="checkbox" :disabled="!!item.errors.length"/><span><strong>{{item.name}}</strong><small>{{item.groupTitle||'Sem grupo'}} · {{item.tvgId||'Sem TVG-ID'}}</small><code>{{item.url}}</code><small v-if="item.errors.length" class="field-error">{{item.errors.join(' · ')}}</small></span></label></div><progress v-if="importing" :value="progress" :max="selected.length">{{progress}} de {{selected.length}}</progress><div class="form-actions"><button class="button button-secondary" type="button" :disabled="importing" @click="emit('close')">Cancelar</button><button class="button button-primary" type="button" :disabled="importing||!selected.length" @click="run">{{importing?'A importar…':`Importar ${selected.length}`}}</button></div></template></section></div></Teleport></template>
